// Range le lien de la session H dans la démarche, pour que l'interface puisse l'afficher.
const demande = $('Démarche à confier à un agent').first().json;
const session = $("Lancer l'agent H").first().json;
const partage = $input.first().json || {};
const lienPublic = partage.share_url
  ? (String(partage.share_url).startsWith('http') ? partage.share_url : 'https://agp.eu.hcompany.ai' + partage.share_url)
  : null;
return [{ json: {
  id: demande.demarche_id,
  resultat_agent: { agent: demande.agent, session_id: session.id || null, lien_session: session.agent_view_url || null, lien_public: lienPublic },
  updated_at: new Date().toISOString(),
} }];

// Traduit la réponse de l'agent H en résultat de démarche, selon l'aide.
const d = $('Démarche à confier à un agent').first().json;
const s = $input.first().json;
const st = s.status?.status ?? s.status;
let r = s.latest_answer;
if (typeof r === 'string') { try { r = JSON.parse(r.replace(/```json|```/g, '').trim()); } catch (e) { r = { texte: r }; } }
r = r || {};
const nombre = v => (typeof v === 'number' ? v : (v !== null && v !== undefined && v !== '' && !isNaN(Number(v)) ? Number(v) : null));
const repondu = ['completed', 'idle'].includes(st);
let lienPublic = null;
try { lienPublic = $('Lien de la session').first().json.resultat_agent?.lien_public || null; } catch (e) {}

let statut = ['failed', 'timed_out', 'interrupted'].includes(st) ? st : 'timed_out';
let connexion = false;
let montant = null;
let etape = null;

if (d.aide_code === 'apl') {
  montant = nombre(r.montant_mensuel);
  const ok = repondu && montant !== null && !String(r.statut || '').startsWith('bloqu');
  if (ok) { statut = 'interrupted'; connexion = true; etape = 'Simulation faite : la demande se finit sur ton espace caf.fr'; }
  else etape = r.etape_bloquante || "La simulation APL ne s'est pas terminée";
} else if (d.aide_code === 'prime_activite') {
  montant = nombre(r.montant_mensuel ?? r.montant_mensuel_estime ?? r.montant);
  const nonEligible = r.eligible === false || /non/i.test(String(r.eligibilite || ''));
  if (nonEligible && montant === null) montant = 0;
  const ok = repondu && r.simulation_terminee !== false && montant !== null;
  if (ok) { statut = 'interrupted'; connexion = true; etape = montant > 0 ? 'Simulation faite : la demande se finit sur ton espace caf.fr' : (r.raison_si_non_eligible || 'Non éligible selon le simulateur'); }
  else etape = (r.informations_manquantes && [].concat(r.informations_manquantes).join(', ')) || "La simulation de prime d'activité ne s'est pas terminée";
} else if (d.aide_code === 'bourse_crous') {
  // Bourse versée sur 10 mois : montant mensuel = annuel / 10 si l'agent ne le donne pas.
  const annuel = nombre(r.montant_annuel);
  montant = nombre(r.montant_mensuel) ?? (annuel !== null ? Math.round(annuel / 10) : null);
  const nonEligible = /non|aucun/i.test(String(r.echelon || ''));
  if (nonEligible && montant === null) montant = 0;
  const ok = repondu && !String(r.statut || '').startsWith('bloqu') && (r.echelon || montant !== null);
  if (ok) { statut = 'interrupted'; connexion = true; etape = montant > 0 ? 'Simulation faite : la demande se fait sur messervices.etudiant.gouv.fr (dossier social étudiant)' : 'Pas de bourse selon le simulateur'; }
  else etape = r.etape_bloquante || "La simulation de bourse ne s'est pas terminée";
} else if (d.aide_code === 'pret_garanti') {
  const resultats = Array.isArray(r.resultats) ? r.resultats : [];
  const ok = repondu && resultats.length > 0;
  if (ok) { statut = 'completed'; etape = null; }
  else etape = 'La comparaison des prêts ne s’est pas terminée';
} else {
  if (repondu) { statut = 'completed'; }
  etape = repondu ? null : "L'agent ne s'est pas terminé";
}

return [{ json: {
  demarche_id: d.demarche_id,
  etudiant_id: d.etudiant_id,
  site: d.site || null,
  agent: d.agent,
  session_id: s.id || null,
  statut,
  connexion_requise: connexion,
  debut: s.created_at || null,
  fin: s.finished_at || new Date().toISOString(),
  montant_lu: montant,
  etape_bloquante: etape,
  erreur: s.status?.error || null,
  resultat: { reponse: r, lien_public: lienPublic, lien_session: s.agent_view_url || null },
  url_retour: d.url_retour,
} }];
